  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Prefix used for resource names and the Name tag."
  type        = string
  default     = "myapp"
}

variable "environment" {
  description = "Environment name applied to all resources via the Environment tag."
  type        = string
  default     = "production"
}

locals {
  name_prefix     = var.project_name
  db_identifier   = "mysql-db-instance"
  db_name         = "appdb"
  master_username = "dbadmin"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 10)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 11)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "mysql" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Multi-AZ private subnet group for the ${local.db_identifier} MySQL instance."

  subnet_ids = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
  ]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

resource "aws_security_group" "mysql" {
  name        = "${local.name_prefix}-mysql-sg"
  description = "Allow MySQL (3306) only from within the VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC only."
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic restricted to the VPC."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql-sg"
  })
}

resource "random_password" "db_master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_lower        = 2
  min_upper        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "${var.project_name}/${var.environment}/db-master-password"
  description             = "Master credentials for the ${local.db_identifier} MySQL instance."
  recovery_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-master-secret"
  })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    engine   = "mysql"
    host     = aws_db_instance.mysql.address
    port     = aws_db_instance.mysql.port
    dbname   = aws_db_instance.mysql.db_name
    username = local.master_username
    password = random_password.db_master_password.result
  })
}

resource "aws_db_instance" "mysql" {
  identifier     = local.db_identifier
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.medium"

  allocated_storage     = 25
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name         = local.db_name
  username        = local.master_username
  password        = random_password.db_master_password.result
  port            = 3306

  db_subnet_group_name   = aws_db_subnet_group.mysql.name
  vpc_security_group_ids = [aws_security_group.mysql.id]
  publicly_accessible    = false

  apply_immediately          = true
  auto_minor_version_upgrade = true
  deletion_protection        = true
  copy_tags_to_snapshot      = true

  backup_retention_period = 7
  backup_window           = "01:00-02:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.db_identifier
  })
}

output "db_master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the MySQL master credentials. Retrieve the password by reading this secret; the plaintext password is never exposed in configuration or outputs."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static provider metadata: AZs available in the current region
data "aws_availability_zones" "available" {
  state = "available"
}

variable "project_name" {
  description = "Project name used for resource naming and the Project tag."
  type        = string
  default     = "myapp"
}

variable "environment" {
  description = "Environment name used for resource naming and the Environment tag."
  type        = string
  default     = "production"
}

locals {
  name_prefix     = "${var.project_name}-${var.environment}"
  master_username = "dbadmin"
  db_name         = "appdb"
  db_port         = 3306

  common_tags = {
    Environment = var.environment
    Project     = var.project_name
    ManagedBy   = "terraform"
  }
}

# --- Network foundation (greenfield: everything is created here) ---

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Subnet group spanning two AZs for ${local.name_prefix} RDS instances"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

# --- Network access control: MySQL reachable only from inside the VPC ---

resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds-sg"
  description = "Allow MySQL traffic only from within the ${local.name_prefix} VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from the VPC CIDR only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rds-sg"
  })
}

# --- Master credentials: generated securely, stored in Secrets Manager ---

resource "random_password" "db_master_password" {
  length           = 24
  special          = true
  override_special = "!#%*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "${local.name_prefix}-db-master-credentials"
  description = "Master credentials for the ${local.name_prefix} primary MySQL instance"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username             = local.master_username
    password             = random_password.db_master_password.result
    engine               = "mysql"
    host                 = aws_db_instance.primary.address
    port                 = local.db_port
    dbname               = local.db_name
    dbInstanceIdentifier = aws_db_instance.primary.identifier
  })
}

# --- Shared parameter group (family matches the pinned engine version) ---

resource "aws_db_parameter_group" "mysql" {
  name        = "${local.name_prefix}-mysql-params"
  family      = "mysql8.0"
  description = "Shared parameter group for ${local.name_prefix} primary and replica"

  parameter {
    name  = "character_set_server"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_client"
    value = "utf8mb4"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql-params"
  })
}

# --- Primary MySQL instance ---

resource "aws_db_instance" "primary" {
  identifier     = "${local.name_prefix}-primary"
  engine         = "mysql"
  engine_version = "8.0.36"
  instance_class = "db.t3.medium"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"

  db_name  = local.db_name
  username = local.master_username
  password = random_password.db_master_password.result

  db_subnet_group_name   = aws_db_subnet_group.main.name
  parameter_group_name   = aws_db_parameter_group.mysql.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  port                = local.db_port
  publicly_accessible = false
  multi_az            = false

  storage_encrypted       = true
  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true

  auto_minor_version_upgrade = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-primary-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-primary"
  })
}

# --- Read replica (native replication, same network, sizing, and encryption) ---

resource "aws_db_instance" "replica" {
  identifier          = "${local.name_prefix}-replica"
  replicate_source_db = aws_db_instance.primary.arn
  instance_class      = "db.t3.medium"

  db_subnet_group_name   = aws_db_subnet_group.main.name
  parameter_group_name   = aws_db_parameter_group.mysql.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  publicly_accessible = false
  storage_encrypted   = true

  copy_tags_to_snapshot      = true
  deletion_protection        = true
  auto_minor_version_upgrade = true

  skip_final_snapshot = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-replica"
  })
}

# --- Outputs ---

output "primary_db_endpoint" {
  description = "Connection endpoint (hostname) of the primary MySQL instance."
  value       = aws_db_instance.primary.address
}

output "replica_db_endpoint" {
  description = "Connection endpoint (hostname) of the MySQL read replica."
  value       = aws_db_instance.replica.address
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the database master credentials (the secret value itself is never exposed)."
  value       = aws_secretsmanager_secret.db_credentials.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

variable "tags" {
  description = "Consistent tags applied across every resource in this configuration."
  type        = map(string)

  default = {
    Project     = "rds-postgres-baseline"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

locals {
  common_tags   = var.tags
  db_identifier = "rds-postgres-baseline"
  db_name       = "appdb"
  db_username   = "appadmin"
  db_port       = 5432
}

# Static provider metadata lookup (AZ availability), no account-state dependency.
data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-vpc" })
}

resource "aws_subnet" "rds_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-subnet-a" })
}

resource "aws_subnet" "rds_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-subnet-b" })
}

resource "aws_db_subnet_group" "rds" {
  name        = "${local.db_identifier}-subnet-group"
  description = "Subnet group for the ${local.db_identifier} RDS PostgreSQL instance."
  subnet_ids  = [aws_subnet.rds_a.id, aws_subnet.rds_b.id]

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-db-subnet-group" })
}

resource "aws_security_group" "rds" {
  name        = "${local.db_identifier}-sg"
  description = "Allow PostgreSQL (5432) only from inside the VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound responses and maintenance traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-sg" })
}

###############################################################################
# Master credentials (generated at apply time, stored in Secrets Manager)
###############################################################################

resource "random_password" "db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${local.db_identifier}/master-credentials"
  description = "Master credentials for the ${local.db_identifier} RDS PostgreSQL instance."

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-master-secret" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Database
###############################################################################

resource "aws_db_parameter_group" "rds" {
  name   = "${local.db_identifier}-params"
  family = "postgres16"

  parameter {
    name  = "log_min_duration_statement"
    value = "5000"
  }

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-parameter-group" })
}

resource "aws_db_instance" "rds" {
  identifier     = local.db_identifier
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  iops                  = 3000
  storage_throughput    = 125

  db_name  = local.db_name
  username = local.db_username
  password = random_password.db_master.result
  port     = local.db_port

  db_subnet_group_name   = aws_db_subnet_group.rds.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  parameter_group_name   = aws_db_parameter_group.rds.name

  multi_az                   = false
  publicly_accessible        = false
  storage_encrypted          = true
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:30-sun:05:30"

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final-snapshot"

  tags = merge(local.common_tags, { Name = local.db_identifier })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.arn
  secret_string = jsonencode({
    engine   = "postgres"
    host     = aws_db_instance.rds.address
    port     = aws_db_instance.rds.port
    dbname   = local.db_name
    username = local.db_username
    password = random_password.db_master.result
  })
}

###############################################################################
# Outputs
###############################################################################

output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) for the RDS PostgreSQL instance."
  value       = aws_db_instance.rds.endpoint
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for naming and tagging (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  env         = lower(var.environment)
  name_prefix = "db-restore-${local.env}"

  vpc_cidr             = "10.0.0.0/16"
  public_subnet_cidrs  = ["10.0.0.0/24", "10.0.1.0/24"]
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.11.0/24"]

  # Master username stored in Secrets Manager; password is generated by random_password.
  db_username   = "dbadmin"
  backup_prefix = "backups/mysql-xtrabackup/"

  tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_password" "db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
}

#-------------------------------------------------------------------------------
# Network foundation
#-------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-public-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-nat"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

#-------------------------------------------------------------------------------
# Database security group
#-------------------------------------------------------------------------------

resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds-sg"
  description = "Allow MySQL (3306) only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC CIDR"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  # No egress rules declared: the database requires no outbound access, and
  # Terraform removes the default allow-all egress rule when none is specified.

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-rds-sg"
  })
}

#-------------------------------------------------------------------------------
# Customer-managed KMS key (RDS storage encryption + S3 backup SSE-KMS)
#-------------------------------------------------------------------------------

resource "aws_kms_key" "rds" {
  description             = "Customer managed key for RDS storage encryption and S3 backup bucket SSE-KMS"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-kms"
  })
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name_prefix}"
  target_key_id = aws_kms_key.rds.key_id
}

#-------------------------------------------------------------------------------
# Backup source bucket (Percona XtraBackup files for MySQL S3 import)
#-------------------------------------------------------------------------------

resource "aws_s3_bucket" "db_backup" {
  bucket        = "${local.name_prefix}-backup-${random_id.suffix.hex}"
  force_destroy = false

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-backup-${random_id.suffix.hex}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.rds.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.db_backup.arn,
          "${aws_s3_bucket.db_backup.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

#-------------------------------------------------------------------------------
# RDS-to-S3 import IAM role
#-------------------------------------------------------------------------------

resource "aws_iam_role" "rds_s3_import" {
  name = "${local.name_prefix}-rds-s3-import"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowRdsAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-rds-s3-import"
  })
}

resource "aws_iam_role_policy" "rds_s3_import" {
  name = "${local.name_prefix}-s3-import-access"
  role = aws_iam_role.rds_s3_import.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListBackupBucket"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.db_backup.arn
      },
      {
        Sid      = "ReadBackupObjects"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource = "${aws_s3_bucket.db_backup.arn}/*"
      }
    ]
  })
}

# The ingestion role must be able to decrypt the SSE-KMS protected backup objects.
resource "aws_iam_policy" "rds_kms_decrypt" {
  name        = "${local.name_prefix}-rds-kms-decrypt"
  description = "Allow the RDS S3 ingestion role to decrypt backup objects protected by the customer managed KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DecryptBackupObjects"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:DescribeKey"]
        Resource = aws_kms_key.rds.arn
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-rds-kms-decrypt"
  })
}

resource "aws_iam_role_policy_attachment" "rds_kms_decrypt" {
  role       = aws_iam_role.rds_s3_import.name
  policy_arn = aws_iam_policy.rds_kms_decrypt.arn
}

#-------------------------------------------------------------------------------
# Master credentials in Secrets Manager
#-------------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${local.name_prefix}/db-master-credentials"
  description = "Master credentials for the ${local.name_prefix}-restored-db MySQL instance"

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-db-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id

  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master.result
  })
}

#-------------------------------------------------------------------------------
# MySQL database restored from S3 (Percona XtraBackup import)
#-------------------------------------------------------------------------------

resource "aws_db_instance" "restored_db" {
  identifier     = "${local.name_prefix}-restored-db"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.medium"

  allocated_storage     = 50
  max_allocated_storage = 200
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_name = "appdb"
  username = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  port                   = 3306
  publicly_accessible    = false
  multi_az               = true

  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-final-${random_id.suffix.hex}"

  # Backup files (Percona XtraBackup format) must be uploaded to
  # s3://<bucket>/backups/mysql-xtrabackup/ before this instance can be created.
  # The bucket and instance are both provisioned in the provider region (us-east-1).
  s3_import {
    source_engine         = "mysql"
    source_engine_version = "8.0"
    bucket_name           = aws_s3_bucket.db_backup.bucket
    bucket_prefix         = local.backup_prefix
    ingestion_role        = aws_iam_role.rds_s3_import.arn
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-restored-db"
  })

  lifecycle {
    prevent_destroy = true
  }
}

#-------------------------------------------------------------------------------
# Outputs
#-------------------------------------------------------------------------------

output "rds_endpoint_address" {
  description = "Connection endpoint (hostname) of the restored MySQL DB instance."
  value       = aws_db_instance.restored_db.address
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the DB master credentials (secret value is never exposed; retrieve it via secretsmanager:GetSecretValue)."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used as the prefix for all resource names."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "production"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  common_tags = {
    Name        = local.name_prefix
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

resource "aws_security_group" "db" {
  name        = "${local.name_prefix}-db-sg"
  description = "Allow inbound PostgreSQL traffic only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from VPC CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Multi-AZ subnet group for the managed PostgreSQL instance"
  subnet_ids  = aws_subnet.private[*].id

  tags = local.common_tags
}

resource "random_id" "final_snapshot_suffix" {
  byte_length = 4
}

resource "aws_db_instance" "main" {
  identifier     = "${local.name_prefix}-db"
  engine         = "postgres"
  engine_version = "15.8"
  instance_class = "db.t3.medium"

  allocated_storage     = 50
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name                     = "appdb"
  username                    = "dbadmin"
  manage_master_user_password = true
  port                        = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]

  publicly_accessible = false
  multi_az            = true

  backup_retention_period = 14
  backup_window           = "02:00-03:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true
  deletion_protection        = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-db-final-snapshot-${random_id.final_snapshot_suffix.hex}"

  enabled_cloudwatch_logs_exports       = ["postgresql", "upgrade"]
  performance_insights_enabled          = true
  performance_insights_retention_period = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db"
  })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "tags" {
  description = "Additional tags applied consistently to all resources."
  type        = map(string)
  default     = {}
}

locals {
  db_identifier               = "myapp-mysql"
  db_name                     = "myappdb"
  db_username                 = "dbadmin"
  vpc_name                    = "myapp-vpc"
  subnet_group_name           = "myapp-rds-subnet-group"
  security_group_name         = "myapp-rds-mysql-sg"
  secret_name                 = "myapp/mysql/master"
  final_snapshot_identifier   = "myapp-mysql-final-snapshot"
  initial_snapshot_identifier = "myapp-mysql-initial-snapshot"

  common_tags = merge(var.tags)
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.vpc_name
  })
}

resource "aws_subnet" "rds_az0" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-rds-az0"
  })
}

resource "aws_subnet" "rds_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-rds-az1"
  })
}

resource "aws_db_subnet_group" "rds" {
  name       = local.subnet_group_name
  subnet_ids = [aws_subnet.rds_az0.id, aws_subnet.rds_az1.id]

  tags = merge(local.common_tags, {
    Name = local.subnet_group_name
  })
}

resource "aws_security_group" "rds" {
  name        = local.security_group_name
  description = "Allow MySQL access only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from the VPC CIDR only"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL traffic restricted to the VPC CIDR"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = local.security_group_name
  })
}

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%*()-_=+[]{}:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = local.secret_name
  description = "Master credentials for the ${local.db_identifier} MySQL instance"

  tags = merge(local.common_tags, {
    Name = local.secret_name
  })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master.result
    engine   = "mysql"
    port     = 3306
    host     = aws_db_instance.mysql.address
    dbname   = aws_db_instance.mysql.db_name
  })
}

resource "aws_db_instance" "mysql" {
  identifier     = local.db_identifier
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true

  db_name  = local.db_name
  username = local.db_username
  password = random_password.db_master.result

  db_subnet_group_name   = aws_db_subnet_group.rds.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  publicly_accessible = false
  multi_az            = false

  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true
  deletion_protection        = true

  skip_final_snapshot       = false
  final_snapshot_identifier = local.final_snapshot_identifier

  timeouts {
    create = "40m"
    update = "80m"
    delete = "60m"
  }

  tags = merge(local.common_tags, {
    Name = local.db_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_snapshot" "mysql_snapshot" {
  db_instance_identifier = aws_db_instance.mysql.identifier
  db_snapshot_identifier = local.initial_snapshot_identifier

  tags = merge(local.common_tags, {
    Name = local.initial_snapshot_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "db_instance_endpoint" {
  description = "Connection endpoint of the MySQL instance."
  value       = aws_db_instance.mysql.endpoint
}

output "db_instance_identifier" {
  description = "Identifier of the MySQL instance."
  value       = aws_db_instance.mysql.identifier
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

output "db_snapshot_identifier" {
  description = "Identifier of the manual MySQL snapshot."
  value       = aws_db_snapshot.mysql_snapshot.db_snapshot_identifier
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Consistent tags (Name, Environment, ManagedBy) applied to every taggable resource in this configuration."
  type        = map(string)

  default = {
    Name        = "efs-shared-storage"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  az_count   = 2
  az_names   = slice(data.aws_availability_zones.available.names, 0, local.az_count)
  account_id = data.aws_caller_identity.current.account_id

  private_subnets = {
    for idx, az in local.az_names :
    az => cidrsubnet(aws_vpc.main.cidr_block, 8, idx + 10)
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(var.tags, {
    Name = "efs-vpc"
  })
}

resource "aws_subnet" "private" {
  for_each          = local.private_subnets
  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value
  availability_zone = each.key

  tags = merge(var.tags, {
    Name = "efs-private-${each.key}"
  })
}

resource "aws_security_group" "efs_mount_targets" {
  name        = "efs-mount-target-sg"
  description = "Permit NFS (TCP 2049) access to EFS mount targets from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from within the VPC CIDR only"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic scoped to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(var.tags, {
    Name = "efs-mount-target-sg"
  })
}

resource "aws_kms_key" "efs" {
  description             = "Customer managed CMK used to encrypt the EFS file system at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMDelegationForAccountRoot"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${local.account_id}:root"
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:Get*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Delete*",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowEFSServiceToUseKeyForThisAccountOnly"
        Effect = "Allow"
        Principal = {
          Service = "elasticfilesystem.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = local.account_id
            "kms:ViaService"    = "elasticfilesystem.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, {
    Name = "efs-encryption-key"
  })
}

resource "aws_kms_alias" "efs" {
  name          = "alias/efs-shared-storage"
  target_key_id = aws_kms_key.efs.key_id
}

resource "aws_efs_file_system" "main" {
  creation_token   = "efs-shared-storage-main"
  performance_mode = "generalPurpose"
  throughput_mode  = "elastic"
  encrypted        = true
  kms_key_id       = aws_kms_key.efs.arn

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  lifecycle_policy {
    transition_to_archive = "AFTER_90_DAYS"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, {
    Name = "efs-shared-storage"
  })
}

resource "aws_efs_mount_target" "main" {
  for_each        = aws_subnet.private
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = each.value.id
  security_groups = [aws_security_group.efs_mount_targets.id]
}

resource "aws_efs_access_point" "app" {
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/app"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "750"
    }
  }

  tags = merge(var.tags, {
    Name = "efs-access-point-app"
  })
}

resource "aws_efs_backup_policy" "main" {
  file_system_id = aws_efs_file_system.main.id

  backup_policy {
    status = "ENABLED"
  }
}

output "efs_file_system_id" {
  description = "ID of the EFS file system."
  value       = aws_efs_file_system.main.id
}

output "efs_dns_name" {
  description = "DNS name of the EFS file system used by clients to mount the share."
  value       = aws_efs_file_system.main.dns_name
}

output "efs_security_group_id" {
  description = "ID of the security group attached to the EFS mount targets."
  value       = aws_security_group.efs_mount_targets.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_name" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "efs-backup"
}

locals {
  name_prefix = "${var.project_name}-${var.environment_name}"

  common_tags = {
    Name        = local.name_prefix
    Environment = var.environment_name
    Project     = var.project_name
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

resource "aws_security_group" "efs" {
  name        = "${local.name_prefix}-efs-mount-target-sg"
  description = "Permits NFS (TCP 2049) ingress only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from within the VPC only"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs-mount-target-sg"
  })
}

resource "aws_kms_key" "efs" {
  description             = "Customer-managed KMS key used to encrypt the EFS file system at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "efs" {
  name          = "alias/${local.name_prefix}-efs"
  target_key_id = aws_kms_key.efs.key_id
}

resource "aws_efs_file_system" "efs" {
  creation_token   = "${local.name_prefix}-efs"
  performance_mode = "generalPurpose"
  throughput_mode  = "elastic"
  encrypted        = true
  kms_key_id       = aws_kms_key.efs.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_backup_policy" "efs" {
  file_system_id = aws_efs_file_system.efs.id

  backup_policy {
    status = "ENABLED"
  }
}

resource "aws_efs_file_system_policy" "efs" {
  file_system_id = aws_efs_file_system.efs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceEncryptionInTransit"
        Effect    = "Deny"
        Principal = { AWS = "*" }
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Resource = aws_efs_file_system.efs.arn
        Condition = {
          BoolIfExists = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_efs_mount_target" "efs" {
  for_each = {
    for idx, subnet_id in aws_subnet.private[*].id : tostring(idx) => subnet_id
  }

  file_system_id  = aws_efs_file_system.efs.id
  subnet_id       = each.value
  security_groups = [aws_security_group.efs.id]
}

output "efs_file_system_id" {
  description = "The ID of the EFS file system."
  value       = aws_efs_file_system.efs.id
}

output "efs_dns_name" {
  description = "The DNS name of the EFS file system (mount point)."
  value       = aws_efs_file_system.efs.dns_name
}

output "efs_backup_policy_status" {
  description = "The status of the EFS automatic backup policy."
  value       = aws_efs_backup_policy.efs.backup_policy[0].status
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-1"
  }
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-2"
  }
}

resource "aws_subnet" "public_3" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-3"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

resource "aws_route_table_association" "public_1_assoc" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2_assoc" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_3_assoc" {
  subnet_id      = aws_subnet.public_3.id
  route_table_id = aws_route_table.public.id
}

output "vpc_id" {
  description = "ID of the main VPC"
  value       = aws_vpc.main.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC"
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "public_subnet_ids" {
  description = "List of public subnet IDs"
  value = [
    aws_subnet.public_1.id,
    aws_subnet.public_2.id,
    aws_subnet.public_3.id,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources"
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  public_subnet_cidrs = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw"
  })
}

resource "aws_subnet" "public" {
  for_each = {
    for idx, az in slice(data.aws_availability_zones.available.names, 0, length(local.public_subnet_cidrs)) :
    az => local.public_subnet_cidrs[idx]
  }

  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = each.value
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "main-public-subnet-${each.key}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "main-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

