}

# SECURITY NOTE (explicit user-requested exception to least-privilege):
# Ingress on TCP 3306 (MySQL) and TCP 5432 (PostgreSQL) is intentionally
# open to 0.0.0.0/0 because the databases must be reachable from any IP
# address. This is the ONLY traffic allowed in from 0.0.0.0/0 besides the
# standard allow-all egress rule; no other ingress ports are opened.
resource "aws_security_group" "database" {
  name        = "database_sg"
  description = "Allow MySQL (3306) and PostgreSQL (5432) from any IP - explicit user-requested exception; all other ingress denied"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from anywhere (explicit user-requested exception)"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "PostgreSQL from anywhere (explicit user-requested exception)"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "database_sg"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "main_db_subnet_group"
  subnet_ids = [aws_subnet.db_a.id, aws_subnet.db_b.id]

  tags = {
    Name = "main_db_subnet_group"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.0.0.0/16"
  assign_generated_ipv6_cidr_block = true

  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "pike-vpc"
  }
}

resource "aws_subnet" "ipv6" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 1)
  availability_zone = data.aws_availability_zones.available.names[0]

  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = true

  tags = {
    Name = "pike-ipv6-subnet"
  }
}

resource "aws_egress_only_internet_gateway" "pike" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "pike"
    permissions = "permissions"
  }
}

resource "aws_route_table" "ipv6_egress" {
  vpc_id = aws_vpc.main.id

  route {
    ipv6_cidr_block        = "::/0"
    egress_only_gateway_id = aws_egress_only_internet_gateway.pike.id
  }

  tags = {
    Name = "pike-ipv6-egress"
  }
}

resource "aws_route_table_association" "ipv6_subnet" {
  subnet_id      = aws_subnet.ipv6.id
  route_table_id = aws_route_table.ipv6_egress.id
}

